import os
from mutagen.easyid3 import EasyID3

music_dir = os.path.expanduser('~/Music')
for root, dirs, files in os.walk(music_dir):
    for file in files:
        if file.endswith('.mp3'):
            audio = EasyID3(os.path.join(root, file))
            if 'title' not in audio:
                audio['title'] = file[:-4]
                audio.save()

